v_NomDossier := @Subset(@IfError(@DbLookup("" : "NoCache"; ""; "V_SIRH21"; @UserName + ";"; 3; [PartialMatch]); "");1);
@If(@IsNull(v_NomDossier); @Return(@Prompt([Ok]; ""; "Aucun dossier de recherche disponible.")); "");
@If(@IsError(@DbColumn("" : "NoCache"; ""; v_NomDossier; 6)); @Return(@Prompt([Ok]; ""; "Aucun dossier de recherche disponible.")); "");
@SetTargetFrame("Contenu");
@Command([OpenView]; v_NomDossier)

REM {Il faut utiliser une vue dans laquelle une colonne contient les UNIDs};
v_Cle :=Tabl_Nom;
v_NomVue := "V_Tabl20";
v_NoColonneUNID := 9;

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; v_NoColonneUNID);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("La table est déjà définie."))

