v_ObligatoireSDSPP := @If(DB_Origine = "SDSP";@Replace(@Replace(DB_Statut;"99";"94"); @IfError(@DbLookup("" : "NoCache"; SF_ServeurSDSPP : SF_FichierSDSPP ;"V_Tabl20"; "Prop_Statut_FR"; 4); ""); @Text(@IfError(@DbLookup("" : "NoCache"; SF_ServeurSDSPP : SF_FichierSDSPP ;"V_Tabl20"; "Prop_Statut_FR"; 14); "")));"");

@If(@IsNull(@ThisValue) & (v_Obligatoire = "1" | v_ObligatoireSDSPP = "1"); @Failure("Le commentaire est obligatoire pour le statut sélectionné."); @Success)

