keywords.formula:
v_VueClie := "V_Clie20";
v_ClientNoFMT := @If(BCom_ClientNo1 = ""; ""; BCom_ClientNo1 > 0; @Text(BCom_ClientNo1) + "-" + BCom_ClientNo2; "");


v_ClientCategorieX:=@IfError(@Text(@DbLookup("":"NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueClie; v_ClientNoFMT; "Clie_ClientCategorie")); "");
v_ClientCategorie := @If(v_ClientCategorieX*="60":"62";"SDS";"");

v_Langue :=  @IfError(@DbLookup("":"NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueClie; v_ClientNoFMT; 13); SF_Langue);

@IfError("":@DbLookup("" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; "Cont_Fonctions" + v_ClientCategorie + v_Langue; 6); "")

v_Cle := "BCom_SousType" + SF_Langue + ";" + BCom_Type;
v_Valeurs := @DbLookup("" : "NoCache"; "" : ""; "V_Tabl20"; v_Cle; 6);
@If(@IsError(v_Valeurs); ""; v_Valeurs)

