v_Nom := @Name([CN]; @UserName);
v_Actif := @IfError(@DbLookup(""; SF_ServeurSIEm : SF_FichierSIEm; "V_Empl24"; v_Nom; 5); "0");
@If(v_Actif = "1"; v_Nom; "")

REM {***** Validations de base};
@If(BCom_ClientNo1 = ""; @Return(@Success); !@Matches(BCom_ClientNo2; "{0123456789}{0123456789}{0123456789}"); @Return(@Failure("La deuxième partie du numéro de client est invalide.")); "");

v_VueSICl := "V_Clie20";
v_CleSICl := @Text(BCom_ClientNo1) + "-" + BCom_ClientNo2;

REM {***** Vérifier l'existence du document};
@If(@IsError(@DbLookup("" : "NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueSICl; v_CleSICl; 1)); @Return(@Failure("Le client est inexistant.")); @Success)

v_Adresse1 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; BCom_ClientNoFmt; 3); "");
v_Adresse2 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; BCom_ClientNoFmt; 4); "");
v_Ville := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; BCom_ClientNoFmt; 5); "");
v_Province := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; BCom_ClientNoFmt; 8); "");
v_CodePostal := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; BCom_ClientNoFmt; 9); "");

@If(v_Adresse2 = ""; v_Adresse1; v_Adresse1 : v_Adresse2) : (v_Ville + "  " + v_Province + "   " + v_CodePostal)

REM {Va chercher la langue dans Si Client};

v_VueClie := "V_Clie20";
v_Cle := BCom_ClientNoFmt;
@If(v_Cle = null;@Return(SF_Langue);null);

@IfError(@DbLookup("":"NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueClie; v_Cle; 13); SF_Langue)

REM {Va chercher la catégorie dans Si Client};

v_VueClie := "V_Clie20";
v_Cle := BCom_ClientNoFmt;

result:=@IfError(@Text(@DbLookup("":"NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueClie; v_Cle; "Clie_ClientCategorie")); "");
@If(result*="60":"62";"SDS";"")

@If(@IsNull(BCom_NoContact) & @IsNull(@ThisValue) &
(BCom_ContactNom != "" |
BCom_AutreContactFonction != "" |
BCom_ContactTelephone != "" |
BCom_ContactPoste != "" |
BCom_ContactCourriel != "");
	@Failure("Le prénom du contact est requis");@Success)

