(BCom_ContactPrenom != "" |
BCom_AutreContactFonction != "" |
BCom_ContactTelephone != "" |
BCom_ContactPoste != "" |
BCom_ContactCourriel != "");
	@Failure("Le nom du contact est requis");@Success)

v_NomTable := "Cont_Fonctions" + BCom_ClientCategorie + BCom_ClientLangue;
v_Cle := BCom_AutreContactFonction;

@Replace(v_Cle; @IfError(@DbLookup( "" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup( "" : "NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 5); ""))

